-- Reference schema. Flyway uses migrations/V1__init.sql as the executable source.
CREATE TYPE order_status AS ENUM ('PENDING','CONFIRMED','SHIPPING','COMPLETED','CANCELLED');
CREATE TYPE payment_status AS ENUM ('PENDING','PAID','FAILED','REFUNDED');
CREATE TABLE users(id BIGSERIAL PRIMARY KEY,email VARCHAR(255) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(150) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'CUSTOMER' CHECK(role IN ('CUSTOMER','STAFF','ADMIN')),enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE categories(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(140) UNIQUE NOT NULL,description TEXT);
CREATE TABLE products(id BIGSERIAL PRIMARY KEY,category_id BIGINT REFERENCES categories(id),slug VARCHAR(180) UNIQUE NOT NULL,name VARCHAR(180) NOT NULL,description TEXT,price NUMERIC(14,2) NOT NULL CHECK(price>=0),stock_quantity INTEGER NOT NULL DEFAULT 0 CHECK(stock_quantity>=0),image_url TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE orders(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),status order_status NOT NULL DEFAULT 'PENDING',recipient_name VARCHAR(150) NOT NULL,phone VARCHAR(30) NOT NULL,shipping_address TEXT NOT NULL,total_amount NUMERIC(14,2) NOT NULL CHECK(total_amount>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE order_items(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES products(id),product_name VARCHAR(180) NOT NULL,unit_price NUMERIC(14,2) NOT NULL CHECK(unit_price>=0),quantity INTEGER NOT NULL CHECK(quantity>0));
CREATE TABLE payments(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id),provider VARCHAR(30) NOT NULL,transaction_ref VARCHAR(120) UNIQUE,status payment_status NOT NULL DEFAULT 'PENDING',amount NUMERIC(14,2) NOT NULL,provider_payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE refresh_tokens(id BIGSERIAL PRIMARY KEY,token_hash VARCHAR(64) UNIQUE NOT NULL,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,revoked BOOLEAN NOT NULL DEFAULT FALSE);
CREATE INDEX idx_products_category ON products(category_id);CREATE INDEX idx_orders_user ON orders(user_id);CREATE INDEX idx_refresh_tokens_user ON refresh_tokens(user_id);
